def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Locate the non-background object and its bounding box.
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] != bg and grid[r][c] != 8]
    if not cells:
        return out
    r0, r1 = min(r for r, c in cells), max(r for r, c in cells)
    c0, c1 = min(c for r, c in cells), max(c for r, c in cells)
    motif = [(r-r0, c-c0, grid[r][c]) for r, c in cells]

    # Each 8 marks the center of a location where the motif is copied.
    cr, cc = (r1-r0)//2, (c1-c0)//2
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 8:
                top, left = r-cr, c-cc
                for dr, dc, color in motif:
                    rr, cc2 = top+dr, left+dc
                    if 0 <= rr < h and 0 <= cc2 < w:
                        out[rr][cc2] = color
    return out
